import pathlib,base64,subprocess,json,time,datetime,hashlib
root=pathlib.Path('/Users/m1/builds/hanlin-ai-788354f8-header-closure-main15/manifest-inputs')
root.mkdir(exist_ok=False)
files={'Package.swift': '', 'Packages/HanlinExpoRuntime/Package.swift': '', 'Packages/HanlinWidgetSDK/Package.swift': ''}
for rel,data in files.items():
 p=root/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(data))
results=[]
for label,rel in [('unified','.'),('expo','Packages/HanlinExpoRuntime'),('widgets','Packages/HanlinWidgetSDK')]:
 cmd=['/usr/bin/xcrun','swift','package','--package-path',str(root/rel),'dump-package']
 start=time.monotonic();done=subprocess.run(cmd,capture_output=True,timeout=30)
 results.append(dict(label=label,command=cmd,exitCode=done.returncode,elapsedSeconds=time.monotonic()-start,stdout=done.stdout.decode(),stderr=done.stderr.decode()))
 if done.returncode: break
print(json.dumps(dict(timestamp=datetime.datetime.now(datetime.timezone.utc).isoformat(),remoteRoot=str(root),sourceSHA256={rel:hashlib.sha256(base64.b64decode(data)).hexdigest() for rel,data in files.items()},results=results)))
